# pairwise marker delta signatures with point pair identities
for a,ma in pieces.items():
 for b,mb in pieces.items():
  if a>=b: continue
  hits=[]
  for i,p in enumerate(ma):
   for j,q in enumerate(ma):
    if i>=j: continue
    d=(q[0]-p[0],q[1]-p[1])
    for k,r in enumerate(mb):
     for l,s in enumerate(mb):
      if k>=l: continue
      if (s[0]-r[0],s[1]-r[1])==d:
       # translation b relative a to align p/r
       hits.append((d,(i,j),(k,l),(p[0]-r[0],p[1]-r[1])))
  if hits: print(a,b,hits)

